def initial_board():
    board = ["."] * 64
    for square, color in (("d4", "W"), ("e5", "W"), ("d5", "B"), ("e4", "B")):
        board[square_index(square)] = color
    return "".join(board)
    def __init__(self):
        self.board = initial_board()
        self.side = "B"
        self.over = False
        self.history = []
        self.redo = []
    def reset(self):
        self.board = initial_board()
        self.side = "B"
        self.over = False
        self.history = []
        self.redo = []
        if command == "NEW":
            self.reset()
            self.emit("OK")
